# Generate B1 writing course content:
#   content/b1-writing.md            (course index)
#   content/b1-writing-unit-1..10.md (10 units x 10 lessons)
#
# B1 target: answer/acceptAlso 100-150 words, core ~55-80 words.
# No double-quotes allowed inside any field (the markdown parser splits on ").
import re, os

CONTENT_DIR = os.path.join(os.path.dirname(__file__), "..", "content")

def wc(s: str) -> int:
    return len(re.findall(r"[A-Za-z']+", s))


def split_paragraphs(text: str) -> str:
    """Turn a model essay into 3 paragraphs using ' || ' as a single-line
    separator (the markdown parser reads fields one line at a time).

    Opening = first sentence, body = middle sentences, ending = last sentence.
    Essays with fewer than 3 sentences are left untouched.
    """
    sents = [s.strip() for s in re.split(r"(?<=[.!?])\s+", text.strip()) if s.strip()]
    if len(sents) < 3:
        return text
    if len(sents) == 3:
        return " || ".join(sents)
    return " || ".join([sents[0], " ".join(sents[1:-1]), sents[-1]])

PALETTE = [
    ("Personal Experiences", "🧭", "#2563EB"),
    ("Opinions & Preferences", "💡", "#7C3AED"),
    ("Travel & Culture", "✈️", "#0891B2"),
    ("Environment & Society", "🌍", "#059669"),
    ("Technology", "🤖", "#DB2777"),
    ("Health & Fitness", "🥗", "#EA580C"),
    ("Education", "🎓", "#9333EA"),
    ("People & Relationships", "🤝", "#0D9488"),
    ("Daily Life", "🏠", "#CA8A04"),
    ("Imagination", "🌟", "#DC2626"),
]

UNITS = []

def build_unit_file(unit_num, theme, icon, color, lessons):
    out = []
    out.append("---")
    out.append(f'unitTitle: "Unit {unit_num}: {theme}"')
    out.append('courseId: "b1-writing"')
    out.append(f'description: "B1 Writing about {theme}"')
    out.append(f'icon: "{icon}"')
    out.append(f'color: "{color}"')
    out.append('targetLanguage: "en"')
    out.append('sourceLanguage: "zh"')
    out.append('level: "B1"')
    out.append('questionType: "writing"')
    out.append("---")
    out.append("")
    for (title, desc, chinese, answer, core, acceptAlso, srs) in lessons:
        out.append("---")
        out.append(f'lessonTitle: "{title}"')
        out.append(f'description: "{desc}"')
        out.append(f'icon: "{icon}"')
        out.append(f'color: "{color}"')
        out.append("---")
        out.append("")
        out.append("[writing]")
        out.append('text: "Write this passage in English in three short paragraphs: an opening, a middle and an ending"')
        out.append(f'sentence: "{chinese}（请写成三段：开头点题、中间展开、结尾收束。字数100-150）"')
        out.append(f'answer: "{split_paragraphs(answer)}"')
        out.append(f'core: "{core}"')
        out.append(f'acceptAlso: "{split_paragraphs(acceptAlso)}"')
        out.append("srsWords: " + " ".join(f'"{w}"' for w in srs.split()))
        out.append("")
    return "\n".join(out)

def build_course_file():
    return "\n".join([
        "---",
        'id: "b1-writing"',
        'courseTitle: "B1 writing"',
        'description: "B1 English writing - write a whole passage from a Chinese prompt"',
        'sourceLanguage: "zh"',
        'targetLanguage: "en"',
        'level: "B1"',
        'visibility: "public"',
        "---",
        "",
    ])

