if __name__ == "__main__":
    with open(os.path.join(CONTENT_DIR, "b1-writing.md"), "w", encoding="utf-8") as f:
        f.write(build_course_file())
    print("wrote b1-writing.md")

    problems = []
    for i, (theme, icon, color) in enumerate(PALETTE, start=1):
        lessons = UNITS[i - 1]
        if len(lessons) != 10:
            problems.append(f"Unit {i} ({theme}) has {len(lessons)} lessons, expected 10")
        text = build_unit_file(i, theme, icon, color, lessons)
        with open(os.path.join(CONTENT_DIR, f"b1-writing-unit-{i}.md"), "w", encoding="utf-8") as f:
            f.write(text)
        for (title, _desc, _zh, answer, core, acceptAlso, _srs) in lessons:
            for label, val, lo, hi in [
                ("answer", answer, 100, 150),
                ("acceptAlso", acceptAlso, 70, 150),
                ("core", core, 48, 82),
            ]:
                n = wc(val)
                if n < lo or n > hi:
                    problems.append(f"Unit {i} '{title}': {label} {n} words (want {lo}-{hi})")
    print("wrote 10 unit files")
    if problems:
        print("PROBLEMS:")
        for p in problems:
            print("  -", p)
        raise SystemExit(1)
    print("ALL WORD COUNTS OK (answer 100-150, acceptAlso 70-150, core 48-82)")
